import java.util.Scanner;

public class Greeter {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Your name: ");
        String name = in.nextLine();
        System.out.print("Your age: ");
        int age = Integer.parseInt(in.nextLine().strip());
        System.out.println("Hi " + name + ", next year you will be " + (age + 1) + ".");
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.List;

public class Notes {
    public static void main(String[] args) throws IOException {
        Path file = Path.of("notes.txt");
        Files.writeString(file, "buy milk\ncall Sam\nwrite Java\n");
        List<String> lines = Files.readAllLines(file);
        System.out.println(lines.size() + " lines");
        for (String line : lines) {
            System.out.println("* " + line);
        }
        Files.writeString(file, "pay rent\n", StandardOpenOption.APPEND);
        System.out.println(Files.readString(file).length());
    }
}
